-- bricx.invitations_guard (ADR 0077, C6): what a CHECK cannot hold, for
-- every role. id, org_id, project_id, role_id, project_role_id,
-- invited_by and created_at never change; a terminal row (accepted,
-- expired, revoked) never changes again; the status moves only from
-- pending; email_normalised changes only to NULL, and only by the accept
-- (pending -> accepted in the same UPDATE). SQLSTATE P6006.
CREATE FUNCTION "bricx"."invitations_guard"() RETURNS trigger
  LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.project_id IS DISTINCT FROM OLD.project_id
     OR NEW.role_id IS DISTINCT FROM OLD.role_id
     OR NEW.project_role_id IS DISTINCT FROM OLD.project_role_id
     OR NEW.invited_by IS DISTINCT FROM OLD.invited_by
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'an invitation keeps its identity'
      USING ERRCODE = 'P6006';
  END IF;
  IF OLD.status <> 'pending' THEN
    RAISE EXCEPTION 'a settled invitation is final'
      USING ERRCODE = 'P6006';
  END IF;
  IF NEW.email_normalised IS DISTINCT FROM OLD.email_normalised
     AND NOT (NEW.email_normalised IS NULL AND NEW.status = 'accepted') THEN
    RAISE EXCEPTION 'an invitation keeps its address until accepted'
      USING ERRCODE = 'P6006';
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER "invitations_guard" BEFORE UPDATE ON "bricx"."invitations" FOR EACH ROW EXECUTE FUNCTION "bricx"."invitations_guard"();
--> statement-breakpoint
-- app.invitation_by_token_hash() (ADR 0077, D1): the API's cross-org
-- lookup of an invitation by the hash of its token's secret, before it
-- knows the org. Returns the id, the org and the inviter only (never the
-- e-mail or the role); the caller then works in that org's withTx() and
-- compares the hash again in constant time. SECURITY DEFINER as
-- bricx_owner through the owner read policy; EXECUTE for bricx_app only.
CREATE FUNCTION "app"."invitation_by_token_hash"(p_hash bytea)
RETURNS TABLE (id uuid, org_id uuid, invited_by uuid)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
BEGIN ATOMIC
  SELECT i.id, i.org_id, i.invited_by
  FROM bricx.invitations i
  WHERE p_hash IS NOT NULL AND octet_length(p_hash) = 32
    AND i.token_hash = p_hash;
END;
