--> statement-breakpoint
GRANT EXECUTE ON FUNCTION "app"."invitation_by_token_hash"(bytea) TO bricx_app;
--> statement-breakpoint
-- app.invitations_due() (ADR 0077, D10): the sweeper's cross-org read of
-- pending invitations past expires_at (oldest first, at most p_limit,
-- 1000 at most); the worker expires each one as bricx_app in its org with
-- its audit event. Writes nothing. SECURITY DEFINER as bricx_owner;
-- EXECUTE for bricx_relay only, as app.access_grants_due().
CREATE FUNCTION "app"."invitations_due"(p_limit integer)
RETURNS TABLE (id uuid, org_id uuid, invited_by uuid)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
BEGIN ATOMIC
  SELECT i.id, i.org_id, i.invited_by
  FROM bricx.invitations i
  WHERE i.status = 'pending' AND i.expires_at <= now()
  ORDER BY i.expires_at, i.id
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 0), 0), 1000);
END;
--> statement-breakpoint
REVOKE ALL ON FUNCTION "app"."invitations_due"(integer) FROM PUBLIC;
--> statement-breakpoint
